/// Checks if `factor` divides `candidate`.
fn divides(factor: u64, candidate: u64) -> bool {
    candidate % factor == 0
}

/// Checks if `candidate` is a prime number.
fn is_prime(candidate: u64) -> bool {
    if candidate <= 1 {
        return false; // By definition, numbers <= 1 are not prime
    }
    if candidate <= 3 {
        return true; // 2 and 3 are prime numbers
    }
    if divides(2, candidate) || divides(3, candidate) {
        return false; // Eliminate multiples of 2 and 3
    }
    
    let mut factor = 5;
    while factor * factor <= candidate {
        if divides(factor, candidate) || divides(factor + 2, candidate) {
            return false; // Check for factors of the form 6k ± 1
        }
        factor += 6; // Move to the next potential prime factor
    }
    
    true // If no factors were found, it's prime
}

/// Tests if the given `candidate` is a prime number.
fn test_prime(candidate: u64) -> bool {
    is_prime(candidate)
}

fn main() {
    // Example usage
    let number = 29;
    println!("Is {} prime? {}", number, test_prime(number)); // Should print true
}